/**
 * Centralized error recovery manager
 * Coordinates retry, circuit breaker, and fallback strategies
 */
export class ErrorRecoveryManager {
    constructor(options?: {});
    options: {
        enabled: boolean;
    };
    retryManager: RetryManager;
    circuitBreaker: CircuitBreaker;
    fallbackManager: FallbackManager;
    errorHistory: Map<any, any>;
    errorRates: Map<any, any>;
    maxErrorHistory: any;
    errorRateWindow: any;
    onError: any;
    /**
     * Execute function with full error recovery pipeline
     * Order: Circuit Breaker -> Retry -> Fallback
     * @param {string} ruleId
     * @param {Function} fn - Primary execution function
     * @param {Function} fallbackFn - Optional fallback execution function
     * @returns {Promise<any>}
     */
    execute(ruleId: string, fn: Function, fallbackFn?: Function): Promise<any>;
    /**
     * Record successful execution
     * @param {string} ruleId
     */
    recordSuccess(ruleId: string): void;
    /**
     * Record error
     * @param {string} ruleId
     * @param {Error} error
     */
    recordError(ruleId: string, error: Error): void;
    /**
     * Get error history for a rule
     * @param {string} ruleId
     * @returns {Array}
     */
    getErrorHistory(ruleId: string): any[];
    /**
     * Get error rate for a rule
     * @param {string} ruleId
     * @returns {Object|null}
     */
    getErrorRate(ruleId: string): Object | null;
    /**
     * Register fallback rule
     * @param {string} ruleId
     * @param {Object} fallbackRule
     */
    registerFallbackRule(ruleId: string, fallbackRule: Object): void;
    /**
     * Register fallback value
     * @param {string} ruleId
     * @param {any} value
     */
    registerFallbackValue(ruleId: string, value: any): void;
    /**
     * Get circuit breaker state
     * @param {string} ruleId
     * @returns {string}
     */
    getCircuitState(ruleId: string): string;
    /**
     * Reset circuit breaker
     * @param {string} ruleId - Optional specific rule
     */
    resetCircuit(ruleId: string): void;
    /**
     * Get comprehensive statistics
     * @returns {Object}
     */
    getStats(): Object;
    /**
     * Clear all history and state
     * @param {string} ruleId - Optional specific rule
     */
    clear(ruleId: string): void;
    /**
     * Cleanup resources
     */
    destroy(): void;
}
import { RetryManager } from './RetryStrategies.js';
import { CircuitBreaker } from './CircuitBreaker.js';
import { FallbackManager } from './FallbackManager.js';
